update.sql:
create table ClientApplicationScopes (
  clientApplication bigint not null,
  scope varchar(255) not null,
  primary key (clientApplication, scope)
);

insert into ClientApplicationScopes (clientApplication, scope)
select id, 'legacy'
from ClientApplication;

create table ClientApplicationAuthorizationCodeScopes (
   authorizationCode bigint not null,
    scope varchar(255) not null,
    primary key (authorizationCode, scope)
);

create table ClientApplicationTokenScopes (
   token bigint not null,
   scope varchar(255) not null,
   primary key (token, scope)
);

create table AtomiReport (
  id bigint not null auto_increment,
  type varchar(255) not null,
  report_id bigint,
  primary key (id)
);
